def extract_json(text: str) -> dict:
    """从 LLM 输出中提取 JSON（兼容 ```json ... ``` 包裹）"""
    text = re.sub(r"```json\s*", "", text)
    text = re.sub(r"```\s*", "", text)
    start = text.find("{")
    if start == -1:
        start = text.find("[")
    if start == -1:
        raise ValueError(f"No JSON found in response: {text[:200]}")
    brace = text[start]
    close = "}" if brace == "{" else "]"
    depth, end = 0, start
    found_close = False
    for i, c in enumerate(text[start:], start):
        if c == brace: depth += 1
        elif c == close: depth -= 1
        if depth == 0:
            end = i + 1
            found_close = True
            break
    if not found_close:
        raise ValueError(
            f"Incomplete JSON: found opening {brace} but no matching {close} "
            f"after {len(text)-start} chars. First 100 chars: {text[start:start+100]}"
        )
    return json.loads(text[start:end])


